// Prefill of the letter tools (cancellation-letter, din-letter, withdrawal-letter, payment-reminder, power-of-attorney,
// receipt, leave-request) from the letter pages of the Vorlagen-Archiv (/vorlagen/briefe/<slug>/): the pages link to
// the tool with ?vorlage=brief-<slug>; the example is a static JSON file of the same origin
// (/vorlagen/data/brief-<slug>.json, generated by network/tools/vorlagen/arc2_sections.py) with the tool id and the
// form values. Nothing about the user leaves the device. A remembered sender (opt-in, shared by all letter tools) is
// kept and never overwritten by the example.
import { el, icon } from './dom.js';
import { vorlageParam, vorlageNotice, vorlageMissing } from './arc-vorlage.js';
import { ensureCss } from './tpl-core.js';

const SENDER_KEY = 'fale-wt-letter-sender';
const SENDER = ['sName', 'sStreet', 'sCity', 'sPhone', 'sMail', 'place'];
const BRIEF_RE = /^(en-)?brief-[a-z0-9]+(-[a-z0-9]+)*$/;

/** The brief id from ?vorlage=…, or null (job examples like ?vorlage=koch are not letters). */
export function briefParam(search = location.search) {
  const q = vorlageParam(search);
  return q && BRIEF_RE.test(q.id) ? q.id : null;
}

/** Loads the example for this tool → data or null (unknown id, other tool, offline). */
export async function loadBrief(tool, id = briefParam()) {
  if (!id) return null;
  try {
    const idx = await (await fetch('/vorlagen/data/index.json', { credentials: 'same-origin' })).json();
    if (!Array.isArray(idx?.ids) || !idx.ids.includes(id)) throw new Error('unknown template');
    const res = await fetch(`/vorlagen/data/${id}.json`, { credentials: 'same-origin' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const data = await res.json();
    if (!data || data.v !== 1 || data.id !== id || data.tool !== tool || !data.fields || typeof data.fields !== 'object') throw new Error('bad data');
    return data;
  } catch (err) {
    console.warn('vorlage', id, err);
    return null;
  }
}

function rememberedSender() {
  try { const x = JSON.parse(localStorage.getItem(SENDER_KEY) || 'null'); return x && typeof x === 'object' ? x : null; } catch { return null; }
}

/**
 * Call at the end of a tool's mountStage. With ?vorlage=brief-…: loads the example, writes its fields into
 * state.values[key] and rebuilds the stage with rebuild() (which mounts the tool's stage again from those values).
 */
export function briefVorlage(tool, key, stage, state, ctx, rebuild) {
  const id = briefParam();
  if (!id) return;
  ensureCss();
  const lang = ctx.lang;
  loadBrief(tool, id).then(data => {
    if (!data) { stage.prepend(vorlageMissing(lang)); return; }
    const v = (state.values[key] ||= {});
    const saved = rememberedSender();
    const keep = saved ? SENDER.filter(k => String(v[k] ?? '').trim()) : [];
    for (const [k, val] of Object.entries(data.fields)) if (!keep.includes(k)) v[k] = val && typeof val === 'object' ? JSON.parse(JSON.stringify(val)) : val;
    stage.replaceChildren();
    rebuild();
    state.results?.clear?.();
    ctx.refresh();
    const de = lang === 'de';
    const back = data.page ? el('a', { class: 'wt-btn wt-btn-quiet', href: data.page }, icon('file'), de ? 'Zurück zur Vorlage' : 'Back to the template') : null;
    stage.prepend(vorlageNotice(lang, {
      title: de ? `Vorlage geladen: ${data.name}` : `Template loaded: ${data.name}`,
      body: de ? `Ersetze Empfänger, Daten und Nummern durch deine eigenen Angaben und lies den Text einmal ganz durch – er ist ein Beispiel, keine Rechtsberatung.${keep.length ? ' Deine gemerkten Absenderangaben bleiben erhalten.' : ' Absender und Empfänger im Beispiel sind erfunden.'}`
        : `Replace the recipient, dates and numbers with your own details and read the whole text once – it is an example, not legal advice.${keep.length ? ' Your remembered sender details were kept.' : ''}`,
    }, back ? [back] : []));
  });
}
